#include "sdk.h"
static ProcessInfo list[8];static UiScene scene;static int window,count,selected;static u32 refreshed;static char status[128];
static void refresh(void){count=api(SYS_PROCESSES,0,(u32)list,8);if(count<0)count=0;if(selected>=count)selected=count-1;}
static void draw(void){ui_begin(&scene);ui_text(&scene,24,52,"原生用户态进程 / PID、线程和私有页数");for(int i=0;i<count;i++){char text[128];number(list[i].pid,text);copy(text+strlen(text),"    ");copy(text+strlen(text),list[i].name);if(i==selected)ui_fill(&scene,20,94+i*30,600,28,0xdce8f8);ui_mono(&scene,26,98+i*30,text,0x24252a);number(list[i].threads,text);ui_mono(&scene,390,98+i*30,text,0x4f657b);number(list[i].pages,text);ui_mono(&scene,490,98+i*30,text,0x4f657b);}ui_button(&scene,24,375,130,"终止所选进程");ui_button(&scene,168,375,100,"刷新");ui_text(&scene,24,332,status);Scene(window,&scene);}
int main(void){window=Window("SINO 原生任务管理器",640,425);if(window<0)return 1;refresh();draw();for(;;){UiEvent e;if(Event(&e)==0&&e.type==MSG_CLICK){if(e.y>=94&&e.y<334)selected=(e.y-94)/30;if(ui_hit(&e,24,375,130,26)&&selected>=0&&selected<count){int r=api(SYS_KILL,list[selected].pid,0,0);copy(status,r<0?"权限不足；F10 可启动系统任务管理器。":"进程已终止。");refresh();}if(ui_hit(&e,168,375,100,26))refresh();draw();}u32 now=(u32)api(SYS_TICKS,0,0,0);if(now-refreshed>=50){refreshed=now;refresh();draw();}Yield(1);}}
